```javascript
import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Rail background plane
  const railGeometry = new THREE.PlaneGeometry(3.6, 0.5);
  const railMaterial = new THREE.MeshStandardNodeMaterial({
    color: 0x14141a,
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    side: THREE.DoubleSide
  });

  const rail = new THREE.Mesh(railGeometry, railMaterial);
  rail.position.z = 0.15;
  group.add(rail);

  // Shadow plane beneath
  const shadowGeometry = new THREE.PlaneGeometry(3.8, 0.6);
  const shadowMaterial = new THREE.ShadowMaterial({ opacity: 0.35 });
  const shadowPlane = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadowPlane.position.set(0, -0.06, 0.14);
  group.add(shadowPlane);

  // Navigation items
  const navItems = [
    'HOME',
    'FEATURES',
    'COLLECTION',
    'PRICING',
    'JOURNAL'
  ];

  const entries = [];
  const itemSpacing = 0.68;
  const totalSpan = (navItems.length - 1) * itemSpacing;
  const startX = -totalSpan / 2;

  navItems.forEach((label, i) => {
    const xPos = startX + i * itemSpacing;
    const isActive = i === 0;

    // Create text via fontAtlas
    const textMesh = ctx.fontAtlas.create(label, {
      family: 'JetBrains Mono',
      size: 13,
      weight: isActive ? 700 : 400,
      letterSpacing: 0.08,
      color: isActive ? 0xe8ecf2 : 0xa6adba
    });

    textMesh.position.set(xPos, 0, 0.16);
    group.add(textMesh);

    entries.push({
      index: i,
      label: label,
      x: xPos,
      mesh: textMesh,
      isActive: isActive
    });
  });

  // Active state underline indicator
  const underlineGeo = new THREE.PlaneGeometry(0.28, 0.025);
  const underlineMat = new THREE.MeshBasicNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8
  });
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(startX, -0.06, 0.17);
  group.add(underline);

  // Track all timelines for cleanup
  const timelines = [];

  // Mount animation: rise-in
  group.position.y = 0.4;
  timelines.push(
    gsap.to(group.position, {
      y: 0,
      duration: 0.7,
      ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)'
    })
  );

  // Event handlers
  group.userData.handlers = {
    setActive(newIndex) {
      if (newIndex < 0 || newIndex >= entries.length) return;

      entries.forEach(entry => {
        entry.isActive = entry.index === newIndex;
        const color = entry.isActive ? 0xe8ecf2 : 0xa6adba;
        entry.mesh.material.color.setHex(color);
      });

      const target = entries[newIndex];
      timelines.push(
        gsap.to(underline.position, {
          x: target.x,
          duration: 0.26,
          ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
          overwrite: 'auto'
        })
      );
    },

    onHover(idx, hovering) {
      if (idx < 0 || idx >= entries.length) return;
      const entry = entries[idx];
      if (entry.isActive) return;

      const color = hovering ? 0xe8ecf2 : 0xa6adba;
      timelines.push(
        gsap.to(entry.mesh.material.color, {
          r: (color >> 16 & 255) / 255,
          g: (color >> 8 & 255) / 255,
          b: (color & 255) / 255,
          duration: 0.16,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
          overwrite: 'auto'
        })
      );
    },

    onPress(idx) {
      if (idx < 0 || idx >= entries.length) return;
      const entry = entries[idx];

      timelines.push(
        gsap.to(entry.mesh.scale, {
          x: 0.97,
          y: 0.97,
          duration: 0.12,
          ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          overwrite: 'auto'
        })
      );

      timelines.push(
        gsap.to(entry.mesh.position, {
          z: 0.13,
          duration: 0.12,
          ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          overwrite: 'auto'
        })
      );
    },

    onRelease(idx) {
      if (idx < 0 || idx >= entries.length) return;
      const entry = entries[idx];

      timelines.push(
        gsap.to(entry.mesh.scale, {
          x: 1,
          y: 1,
          duration: 0.12,
          ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          overwrite: 'auto'
        })
      );

      timelines.push(
        gsap.to(entry.mesh.position, {
          z: 0.16,
          duration: 0.12,
          ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          overwrite: 'auto'
        })
      );
    }
  };

  // Cleanup
  group.userData.cleanup = function() {
    timelines.forEach(tl => {
      if (tl && tl.kill) tl.kill();
    });
    gsap.killTweensOf([group, underline, ...entries.map(e => e.mesh)]);

    railGeometry.dispose();
    railMaterial.dispose();
    shadowGeometry.dispose();
    shadowMaterial.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();

    entries.forEach(entry => {
      entry.mesh.geometry?.dispose();
      entry.mesh.material?.dispose();
    });
  };

  return group;
}
